INSERT INTO public.skill_quiz_configs
  (skill_code, region, questions_to_show, selection_mode, selected_ids, pass_score, active)
INSERT INTO public.worker_skill_quiz_items
  (skill_code, question, question_hi, options, correct_option, sort_order)
VALUES
  ('Automotive Sewing Machine Operator / Seamstress', 'What should you check before starting a sewing machine?', 'सिलाई मशीन शुरू करने से पहले क्या जाँचना चाहिए?', '[{"id":"A","en":"Machine condition and safety","hi":"मशीन की स्थिति और सुरक्षा"},{"id":"B","en":"Only the chair","hi":"केवल कुर्सी"},{"id":"C","en":"Only the room light","hi":"केवल कमरे की लाइट"},{"id":"D","en":"Nothing","hi":"कुछ नहीं"}]'::jsonb, 'A', 1),
  ('Automotive Sewing Machine Operator / Seamstress', 'What is the main purpose of a sewing machine?', 'सिलाई मशीन का मुख्य काम क्या है?', '[{"id":"A","en":"Cut metal","hi":"धातु काटना"},{"id":"B","en":"Join fabric with stitches","hi":"टाँकों से कपड़ा जोड़ना"},{"id":"C","en":"Wash clothes","hi":"कपड़े धोना"},{"id":"D","en":"Pack food","hi":"खाना पैक करना"}]'::jsonb, 'B', 2),
  ('Automotive Sewing Machine Operator / Seamstress', 'What should you do if the needle breaks?', 'यदि सुई टूट जाए तो क्या करना चाहिए?', '[{"id":"A","en":"Continue sewing","hi":"सिलाई जारी रखें"},{"id":"B","en":"Hide the broken needle","hi":"टूटी सुई छिपाएँ"},{"id":"C","en":"Stop the machine and inform the supervisor","hi":"मशीन रोककर सुपरवाइज़र को बताएँ"},{"id":"D","en":"Pull the fabric forcefully","hi":"कपड़े को जोर से खींचें"}]'::jsonb, 'C', 3),
  ('Automotive Sewing Machine Operator / Seamstress', 'Why is correct thread tension important?', 'धागे का सही तनाव क्यों जरूरी है?', '[{"id":"A","en":"To make the machine heavier","hi":"मशीन भारी करने के लिए"},{"id":"B","en":"To increase noise","hi":"आवाज बढ़ाने के लिए"},{"id":"C","en":"To change the room temperature","hi":"कमरे का तापमान बदलने के लिए"},{"id":"D","en":"To make neat and strong stitches","hi":"साफ और मजबूत टाँके बनाने के लिए"}]'::jsonb, 'D', 4),
  ('Automotive Sewing Machine Operator / Seamstress', 'What should you do if the thread keeps breaking?', 'यदि धागा बार-बार टूटता है तो क्या करें?', '[{"id":"A","en":"Stop and check the thread or machine","hi":"रुककर धागे या मशीन की जाँच करें"},{"id":"B","en":"Pull harder","hi":"ज्यादा जोर लगाएँ"},{"id":"C","en":"Ignore the problem","hi":"समस्या को नजरअंदाज करें"},{"id":"D","en":"Switch off all factory lights","hi":"फैक्ट्री की सभी लाइट बंद करें"}]'::jsonb, 'A', 5),
  ('Automotive Sewing Machine Operator / Seamstress', 'How should fabric be positioned while sewing?', 'सिलाई करते समय कपड़ा कैसे रखना चाहिए?', '[{"id":"A","en":"Fold it randomly","hi":"मनमाने ढंग से मोड़ें"},{"id":"B","en":"Align it according to the instructions","hi":"निर्देशों के अनुसार सही रखें"},{"id":"C","en":"Keep it under the chair","hi":"कुर्सी के नीचे रखें"},{"id":"D","en":"Hold it away from the machine","hi":"मशीन से दूर रखें"}]'::jsonb, 'B', 6),
  ('Automotive Sewing Machine Operator / Seamstress', 'What should you do before cleaning the machine?', 'मशीन साफ करने से पहले क्या करें?', '[{"id":"A","en":"Increase speed","hi":"गति बढ़ाएँ"},{"id":"B","en":"Continue sewing","hi":"सिलाई जारी रखें"},{"id":"C","en":"Switch it off and follow safety instructions","hi":"मशीन बंद करके सुरक्षा निर्देश मानें"},{"id":"D","en":"Pour water on it","hi":"उस पर पानी डालें"}]'::jsonb, 'C', 7),
  ('Automotive Sewing Machine Operator / Seamstress', 'Why should measurements be checked?', 'माप की जाँच क्यों करनी चाहिए?', '[{"id":"A","en":"To make fabric dirty","hi":"कपड़ा गंदा करने के लिए"},{"id":"B","en":"To waste time","hi":"समय बर्बाद करने के लिए"},{"id":"C","en":"To increase machine noise","hi":"मशीन की आवाज बढ़ाने के लिए"},{"id":"D","en":"To ensure the garment is the correct size","hi":"कपड़े का सही आकार सुनिश्चित करने के लिए"}]'::jsonb, 'D', 8),
  ('Automotive Sewing Machine Operator / Seamstress', 'What should you do if a garment has a defective stitch?', 'यदि कपड़े में टाँका खराब है तो क्या करें?', '[{"id":"A","en":"Report it and correct it according to instructions","hi":"बताकर निर्देशानुसार सुधारें"},{"id":"B","en":"Pack it without checking","hi":"बिना जाँच पैक करें"},{"id":"C","en":"Throw away all garments","hi":"सारे कपड़े फेंक दें"},{"id":"D","en":"Hide the defect","hi":"खराबी छिपाएँ"}]'::jsonb, 'A', 9),
  ('Automotive Sewing Machine Operator / Seamstress', 'How should scissors and needles be handled?', 'कैंची और सुई को कैसे संभालना चाहिए?', '[{"id":"A","en":"Leave them on the floor","hi":"फर्श पर छोड़ दें"},{"id":"B","en":"Handle carefully and store safely","hi":"सावधानी से संभालें और सुरक्षित रखें"},{"id":"C","en":"Throw them to a colleague","hi":"सहकर्मी की ओर फेंकें"},{"id":"D","en":"Keep them inside clothing","hi":"कपड़ों के अंदर रखें"}]'::jsonb, 'B', 10),
  ('Automobile Factory – Production & Quality Control Worker', 'What is the main purpose of quality inspection?', 'गुणवत्ता जाँच का मुख्य उद्देश्य क्या है?', '[{"id":"A","en":"Finish work faster at any cost","hi":"किसी भी कीमत पर जल्दी काम करना"},{"id":"B","en":"Identify defects and ensure quality","hi":"खराबियाँ पहचानना और गुणवत्ता सुनिश्चित करना"},{"id":"C","en":"Increase noise","hi":"शोर बढ़ाना"},{"id":"D","en":"Avoid checking products","hi":"उत्पाद जाँचने से बचना"}]'::jsonb, 'B', 1),
  ('Automobile Factory – Production & Quality Control Worker', 'What should you do if you find a defective part?', 'खराब पार्ट मिलने पर क्या करना चाहिए?', '[{"id":"A","en":"Hide it","hi":"छिपाएँ"},{"id":"B","en":"Mix it with good parts","hi":"अच्छे पार्ट्स में मिला दें"},{"id":"C","en":"Report it according to procedure","hi":"प्रक्रिया के अनुसार रिपोर्ट करें"},{"id":"D","en":"Send it without inspection","hi":"बिना जाँच भेज दें"}]'::jsonb, 'C', 2),
  ('Automobile Factory – Production & Quality Control Worker', 'Why is wearing PPE important?', 'PPE पहनना क्यों जरूरी है?', '[{"id":"A","en":"To protect against workplace hazards","hi":"कार्यस्थल के खतरों से सुरक्षा के लिए"},{"id":"B","en":"To decorate the uniform","hi":"यूनिफॉर्म सजाने के लिए"},{"id":"C","en":"To slow down production","hi":"उत्पादन धीमा करने के लिए"},{"id":"D","en":"To avoid instructions","hi":"निर्देशों से बचने के लिए"}]'::jsonb, 'A', 3),
  ('Automobile Factory – Production & Quality Control Worker', 'What should you do before operating a machine?', 'मशीन चलाने से पहले क्या करें?', '[{"id":"A","en":"Remove safety guards","hi":"सुरक्षा गार्ड हटाएँ"},{"id":"B","en":"Touch moving parts","hi":"चलते पार्ट्स छुएँ"},{"id":"C","en":"Ignore warning signs","hi":"चेतावनी नजरअंदाज करें"},{"id":"D","en":"Check safety and follow instructions","hi":"सुरक्षा जाँचें और निर्देश मानें"}]'::jsonb, 'D', 4),
  ('Automobile Factory – Production & Quality Control Worker', 'Why must product specifications be followed?', 'उत्पाद के निर्धारित मानकों का पालन क्यों जरूरी है?', '[{"id":"A","en":"To change the product randomly","hi":"उत्पाद मनमाने ढंग से बदलने के लिए"},{"id":"B","en":"To meet required quality standards","hi":"आवश्यक गुणवत्ता मानक पूरे करने के लिए"},{"id":"C","en":"To avoid teamwork","hi":"टीमवर्क से बचने के लिए"},{"id":"D","en":"To increase waste","hi":"बर्बादी बढ़ाने के लिए"}]'::jsonb, 'B', 5),
  ('Automobile Factory – Production & Quality Control Worker', 'What should you do if a machine makes an unusual noise?', 'मशीन से असामान्य आवाज आए तो क्या करें?', '[{"id":"A","en":"Ignore it","hi":"नजरअंदाज करें"},{"id":"B","en":"Increase its speed","hi":"गति बढ़ाएँ"},{"id":"C","en":"Report it and follow safety procedures","hi":"रिपोर्ट करें और सुरक्षा प्रक्रिया अपनाएँ"},{"id":"D","en":"Put your hand inside","hi":"हाथ अंदर डालें"}]'::jsonb, 'C', 6),
  ('Automobile Factory – Production & Quality Control Worker', 'What is an assembly line?', 'असेंबली लाइन क्या होती है?', '[{"id":"A","en":"A sequence of production workstations","hi":"उत्पादन कार्यस्थलों की क्रमबद्ध व्यवस्था"},{"id":"B","en":"A staff dining room","hi":"कर्मचारियों का भोजन कक्ष"},{"id":"C","en":"A parking area","hi":"पार्किंग क्षेत्र"},{"id":"D","en":"A cleaning product","hi":"सफाई का सामान"}]'::jsonb, 'A', 7),
  ('Automobile Factory – Production & Quality Control Worker', 'Why should production records be accurate?', 'उत्पादन रिकॉर्ड सही रखना क्यों जरूरी है?', '[{"id":"A","en":"To make more paperwork","hi":"कागजी काम बढ़ाने के लिए"},{"id":"B","en":"To delay production","hi":"उत्पादन में देरी के लिए"},{"id":"C","en":"To avoid responsibility","hi":"जिम्मेदारी से बचने के लिए"},{"id":"D","en":"To track production and quality","hi":"उत्पादन और गुणवत्ता का रिकॉर्ड रखने के लिए"}]'::jsonb, 'D', 8),
  ('Automobile Factory – Production & Quality Control Worker', 'What should you do if you do not understand a work instruction?', 'काम का निर्देश समझ न आए तो क्या करें?', '[{"id":"A","en":"Guess the procedure","hi":"अंदाजा लगाएँ"},{"id":"B","en":"Ask the supervisor for clarification","hi":"सुपरवाइज़र से स्पष्ट करवाएँ"},{"id":"C","en":"Stop following all instructions","hi":"सभी निर्देश मानना बंद करें"},{"id":"D","en":"Copy another worker without asking","hi":"बिना पूछे दूसरे की नकल करें"}]'::jsonb, 'B', 9),
  ('Automobile Factory – Production & Quality Control Worker', 'Why should tools be kept in their designated places?', 'औजार निर्धारित जगह पर क्यों रखने चाहिए?', '[{"id":"A","en":"To hide them","hi":"छिपाने के लिए"},{"id":"B","en":"To make the area crowded","hi":"जगह भरने के लिए"},{"id":"C","en":"To improve safety and accessibility","hi":"सुरक्षा और आसानी से उपलब्धता के लिए"},{"id":"D","en":"To increase production defects","hi":"उत्पादन की खराबियाँ बढ़ाने के लिए"}]'::jsonb, 'C', 10),
  ('Automotive Seat Belt Production Worker', 'What is the main purpose of a car seat belt?', 'कार की सीट बेल्ट का मुख्य उद्देश्य क्या है?', '[{"id":"A","en":"Decorate the seat","hi":"सीट सजाना"},{"id":"B","en":"Reduce injury risk during a collision","hi":"टक्कर के दौरान चोट का जोखिम कम करना"},{"id":"C","en":"Increase vehicle speed","hi":"गाड़ी की गति बढ़ाना"},{"id":"D","en":"Keep the window closed","hi":"खिड़की बंद रखना"}]'::jsonb, 'B', 1),
  ('Automotive Seat Belt Production Worker', 'What should you do if a seat belt has damaged stitching?', 'सीट बेल्ट की सिलाई खराब हो तो क्या करें?', '[{"id":"A","en":"Ignore it","hi":"नजरअंदाज करें"},{"id":"B","en":"Hide the damage","hi":"खराबी छिपाएँ"},{"id":"C","en":"Report it and separate the defective item","hi":"रिपोर्ट करें और खराब उत्पाद अलग रखें"},{"id":"D","en":"Pack it immediately","hi":"तुरंत पैक करें"}]'::jsonb, 'C', 2),
  ('Automotive Seat Belt Production Worker', 'Why is correct assembly important?', 'सही असेंबली क्यों जरूरी है?', '[{"id":"A","en":"For product safety and proper function","hi":"उत्पाद की सुरक्षा और सही कार्य के लिए"},{"id":"B","en":"To change the colour","hi":"रंग बदलने के लिए"},{"id":"C","en":"To increase waste","hi":"बर्बादी बढ़ाने के लिए"},{"id":"D","en":"To reduce inspection","hi":"जाँच कम करने के लिए"}]'::jsonb, 'A', 3),
  ('Automotive Seat Belt Production Worker', 'What should you do if a component is missing?', 'कोई पार्ट गायब हो तो क्या करें?', '[{"id":"A","en":"Use another random part","hi":"कोई भी दूसरा पार्ट लगा दें"},{"id":"B","en":"Ignore it","hi":"नजरअंदाज करें"},{"id":"C","en":"Send the product forward","hi":"उत्पाद आगे भेज दें"},{"id":"D","en":"Follow the work instructions and report it","hi":"निर्देशों का पालन कर रिपोर्ट करें"}]'::jsonb, 'D', 4),
  ('Automotive Seat Belt Production Worker', 'Why should the correct tools be used?', 'सही औजार इस्तेमाल करना क्यों जरूरी है?', '[{"id":"A","en":"To make work difficult","hi":"काम कठिन करने के लिए"},{"id":"B","en":"To assemble parts correctly and safely","hi":"पार्ट्स को सही और सुरक्षित जोड़ने के लिए"},{"id":"C","en":"To avoid checking","hi":"जाँच से बचने के लिए"},{"id":"D","en":"To damage components","hi":"पार्ट्स खराब करने के लिए"}]'::jsonb, 'B', 5),
  ('Automotive Seat Belt Production Worker', 'What should you do before clearing a machine jam?', 'मशीन जाम होने पर उसे ठीक करने से पहले क्या करें?', '[{"id":"A","en":"Reach into moving parts","hi":"चलते पार्ट्स में हाथ डालें"},{"id":"B","en":"Ask a colleague to pull the parts","hi":"सहकर्मी से पार्ट्स खिंचवाएँ"},{"id":"C","en":"Follow the machine isolation procedure and get authorised help","hi":"मशीन को सुरक्षित रूप से अलग कर अधिकृत सहायता लें"},{"id":"D","en":"Increase the machine speed","hi":"गति बढ़ाएँ"}]'::jsonb, 'C', 6),
  ('Automotive Seat Belt Production Worker', 'Why is traceability important in production?', 'उत्पादन में ट्रेसबिलिटी क्यों जरूरी है?', '[{"id":"A","en":"To identify the batch or product history","hi":"बैच या उत्पाद का रिकॉर्ड पहचानने के लिए"},{"id":"B","en":"To hide defective products","hi":"खराब उत्पाद छिपाने के लिए"},{"id":"C","en":"To make packaging colourful","hi":"पैकिंग रंगीन करने के लिए"},{"id":"D","en":"To avoid records","hi":"रिकॉर्ड से बचने के लिए"}]'::jsonb, 'A', 7),
  ('Automotive Seat Belt Production Worker', 'What should you do if a test result fails?', 'टेस्ट का परिणाम असफल हो तो क्या करें?', '[{"id":"A","en":"Change the result","hi":"परिणाम बदल दें"},{"id":"B","en":"Ignore the test","hi":"टेस्ट नजरअंदाज करें"},{"id":"C","en":"Approve the product anyway","hi":"फिर भी मंजूर करें"},{"id":"D","en":"Follow rejection and reporting procedures","hi":"रिजेक्शन और रिपोर्टिंग प्रक्रिया अपनाएँ"}]'::jsonb, 'D', 8),
  ('Automotive Seat Belt Production Worker', 'Why must seat belts be handled carefully?', 'सीट बेल्ट सावधानी से क्यों संभालनी चाहिए?', '[{"id":"A","en":"They are only decorative","hi":"वे केवल सजावटी हैं"},{"id":"B","en":"They are safety-critical components","hi":"वे सुरक्षा के लिए महत्वपूर्ण पार्ट्स हैं"},{"id":"C","en":"They do not need inspection","hi":"उन्हें जाँच की जरूरत नहीं"},{"id":"D","en":"They are disposable packaging","hi":"वे फेंकने वाली पैकिंग हैं"}]'::jsonb, 'B', 9),
  ('Automotive Seat Belt Production Worker', 'What should you do if you are unsure about an assembly step?', 'असेंबली का कोई चरण समझ न आए तो क्या करें?', '[{"id":"A","en":"Guess and continue","hi":"अंदाजा लगाकर आगे बढ़ें"},{"id":"B","en":"Copy without checking","hi":"बिना जाँच नकल करें"},{"id":"C","en":"Ask the supervisor or trainer","hi":"सुपरवाइज़र या ट्रेनर से पूछें"},{"id":"D","en":"Skip the step","hi":"चरण छोड़ दें"}]'::jsonb, 'C', 10);
