-- Test 1 papers for three Czech listings: sewing, auto-factory quality, and seat belts.
-- Hotel housekeeping is not included. Pass mark stays 6/10.

SELECT v.skill_code, NULL, 10, 'random_active', '{}'::uuid[], 60, true
FROM (VALUES
  ('Automotive Sewing Machine Operator / Seamstress'),
  ('Automobile Factory – Production & Quality Control Worker'),
  ('Automotive Seat Belt Production Worker')
) AS v(skill_code)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.skill_quiz_configs c
  WHERE c.skill_code = v.skill_code
    AND c.region IS NULL
);

DELETE FROM public.worker_skill_quiz_responses
WHERE quiz_item_id IN (
  SELECT id
  FROM public.worker_skill_quiz_items
  WHERE skill_code IN ('Automotive Sewing Machine Operator / Seamstress', 'Automobile Factory – Production & Quality Control Worker', 'Automotive Seat Belt Production Worker')
);

DELETE FROM public.worker_skill_quiz_items
WHERE skill_code IN ('Automotive Sewing Machine Operator / Seamstress', 'Automobile Factory – Production & Quality Control Worker', 'Automotive Seat Belt Production Worker');

